import Foundation
import Dispatch

enum Role: Int, Comparable {
    case guest = 0
    case user = 1
    case editor = 2
    case admin = 3

    static func < (lhs: Role, rhs: Role) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct Document {
    let id: String
    let title: String
    let content: String
    let requiredRole: Role
    let ownerId: String
}

struct IndexEntry {
    let documentId: String
    let snippet: String
    let relevanceScore: Double
}

class AccessControlManager {
    private let sessionStore = DispatchQueue(label: "com.search.sessions", attributes: .concurrent)
    private var sessions: [String: (role: Role, userId: String, validUntil: Date)] = [:]

    func createSession(token: String, role: Role, userId: String, ttl: TimeInterval = 300) {
        sessionStore.async(flags: .barrier) {
            self.sessions[token] = (role: role, userId: userId, validUntil: Date().addingTimeInterval(ttl))
        }
    }

    func revokeSession(token: String) {
        sessionStore.async(flags: .barrier) {
            self.sessions.removeValue(forKey: token)
        }
    }

    func getSessionInfo(token: String) -> (role: Role, userId: String)? {
        var result: (role: Role, userId: String)? = nil
        sessionStore.sync {
            if let session = self.sessions[token] {
                if session.validUntil > Date() {
                    result = (role: session.role, userId: session.userId)
                }
            }
        }
        return result
    }

    func validateAccess(token: String, requiredRole: Role) -> Bool {
        guard let info = getSessionInfo(token: token) else { return false }
        return info.role >= requiredRole
    }
}

class SearchIndexService {
    private let accessControl: AccessControlManager
    private let indexQueue = DispatchQueue(label: "com.search.index", attributes: .concurrent)
    private var documentStore: [String: Document] = [:]
    private var invertedIndex: [String: [IndexEntry]] = [:]

    init(accessControl: AccessControlManager) {
        self.accessControl = accessControl
    }

    func addDocument(_ doc: Document) {
        indexQueue.async(flags: .barrier) {
            self.documentStore[doc.id] = doc
            let words = doc.content.lowercased().split(separator: " ").map(String.init)
            for (offset, word) in words.enumerated() {
                let score = 1.0 / Double(offset + 1)
                let entry = IndexEntry(documentId: doc.id, snippet: self.extractSnippet(doc.content, around: offset), relevanceScore: score)
                self.invertedIndex[word, default: []].append(entry)
            }
        }
    }

    func search(query: String, token: String, completion: @escaping ([IndexEntry]) -> Void) {
        // Step 1: Validate the user has at least guest access
        guard let sessionInfo = accessControl.getSessionInfo(token: token) else {
            completion([])
            return
        }

        let userRole = sessionInfo.role
        let userId = sessionInfo.userId

        // Step 2: Perform the search on the index queue
        indexQueue.async {
            let terms = query.lowercased().split(separator: " ").map(String.init)
            var candidates: [IndexEntry] = []

            for term in terms {
                if let entries = self.invertedIndex[term] {
                    candidates.append(contentsOf: entries)
                }
            }

            // Step 3: Filter results based on access control
            let filtered = self.filterByAccess(
                candidates: candidates,
                userRole: userRole,
                userId: userId
            )

            let sorted = filtered.sorted { $0.relevanceScore > $1.relevanceScore }
            let topResults = Array(sorted.prefix(20))
            completion(topResults)
        }
    }

    private func filterByAccess(candidates: [IndexEntry], userRole: Role, userId: String) -> [IndexEntry] {
        return candidates.filter { entry in
            guard let doc = self.documentStore[entry.documentId] else { return false }
            // Allow access if user's role meets requirement OR user owns the document
            return userRole >= doc.requiredRole || doc.ownerId == userId
        }
    }

    func updateDocumentAccess(documentId: String, newRequiredRole: Role, token: String) -> Bool {
        guard accessControl.validateAccess(token: token, requiredRole: .admin) else {
            return false
        }

        indexQueue.async(flags: .barrier) {
            if var doc = self.documentStore[documentId] {
                let updated = Document(id: doc.id, title: doc.title, content: doc.content, requiredRole: newRequiredRole, ownerId: doc.ownerId)
                self.documentStore[documentId] = updated
            }
        }
        return true
    }

    private func extractSnippet(_ content: String, around position: Int) -> String {
        let words = content.split(separator: " ")
        let start = max(0, position - 3)
        let end = min(words.count, position + 4)
        return words[start..<end].joined(separator: " ")
    }
}

// Usage demonstration
let acm = AccessControlManager()
let searchService = SearchIndexService(accessControl: acm)

// Setup: admin adds a classified document
acm.createSession(token: "admin-token", role: .admin, userId: "admin1")
acm.createSession(token: "user-token", role: .user, userId: "user1")

let classifiedDoc = Document(id: "secret-001", title: "Classified Report", content: "nuclear launch codes alpha bravo charlie", requiredRole: .admin, ownerId: "admin1")
searchService.addDocument(classifiedDoc)

